Romanos 9 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que Paulo diz sentir em relação aos seus compatriotas israelitas?","o":["Alegria e gratidão","Grande tristeza e dor incessante","Indiferença","Raiva e decepção"],"c":1,"v":2,"e":"No versículo 2, Paulo diz ter grande tristeza e dor incessante no coração."},
 {"t":"multipla","p":"Segundo a citação de Paulo, por meio de quem seria chamada a descendência de Abraão?","o":["Ismael","Jacó","Isaque","Esaú"],"c":2,"v":7,"e":"O versículo 7 cita: \"Por meio de Isaque será chamada a tua descendência.\""},
 {"t":"multipla","p":"O que foi dito a Rebeca antes de os gêmeos nascerem?","o":["O maior servirá ao mais jovem","Os dois serão grandes nações iguais","O mais jovem servirá ao maior","Um dos filhos não sobreviverá"],"c":0,"v":12,"e":"O versículo 12 registra: \"O maior servirá ao mais jovem.\""},
 {"t":"multipla","p":"A quem a Escritura diz: \"Para isso mesmo te levantei, para mostrar em ti o meu poder\"?","o":["Moisés","Abraão","Esaú","Faraó"],"c":3,"v":17,"e":"O versículo 17 diz que a Escritura fala essas palavras a Faraó."},
 {"t":"multipla","p":"Que imagem Paulo usa para mostrar que a obra não pode contestar o seu Criador?","o":["O pastor e as ovelhas","O oleiro e o barro","O semeador e a semente","A videira e os ramos"],"c":1,"v":21,"e":"No versículo 21, Paulo fala do oleiro que tem direito sobre o barro para fazer vasos para honra e para desonra."},
 {"t":"cv","p":"Paulo cita Oséias: \"Chamarei meu povo ao que não era meu povo.\"","c":true,"v":25,"e":"O versículo 25 traz essa citação de Oséias."},
 {"t":"cv","p":"Segundo a citação de Isaías, todos os filhos de Israel, numerosos como a areia do mar, serão salvos.","c":false,"v":27,"e":"O versículo 27 diz que, mesmo sendo numerosos como a areia do mar, é o remanescente que será salvo."},
 {"t":"cv","p":"Israel não alcançou a lei da justiça porque a buscou pela fé.","c":false,"v":32,"e":"O versículo 32 diz que Israel não a alcançou porque não buscou pela fé, mas como que pelas obras da lei."}
]}

Romanos 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que quem julga o outro condena a si mesmo?","o":["Porque não conhece a lei","Porque julga sem testemunhas","Porque pratica as mesmas coisas que condena","Porque não é judeu"],"c":2,"v":1,"e":"O versículo 1 diz que quem julga se condena, já que pratica as mesmas coisas que condena."},
 {"t":"multipla","p":"Segundo o capítulo, o que conduz a pessoa ao arrependimento?","o":["O medo do castigo","A bondade de Deus","O ensino da lei","A circuncisão"],"c":1,"v":4,"e":"O versículo 4 afirma que é a bondade de Deus que conduz ao arrependimento."},
 {"t":"multipla","p":"Como Deus recompensará cada um?","o":["Conforme a sua origem","Conforme o que ouviu da lei","Conforme a sua circuncisão","Conforme o seu comportamento"],"c":3,"v":6,"e":"O versículo 6 diz que Deus recompensará a cada um conforme o seu comportamento."},
 {"t":"multipla","p":"Quem será justificado diante de Deus?","o":["Os que praticam a lei","Os que ouvem a lei","Os que ensinam a lei","Os que nasceram judeus"],"c":0,"v":13,"e":"O versículo 13 diz que não os simples ouvintes, mas os que praticam a lei serão justificados."},
 {"t":"multipla","p":"O que acontece entre os gentios por causa de quem transgride a lei?","o":["Os gentios se convertem","Os templos são destruídos","O nome de Deus é blasfemado","A lei é esquecida"],"c":2,"v":24,"e":"O versículo 24 diz que o nome de Deus é blasfemado entre os gentios por causa deles."},
 {"t":"cv","p":"Deus julgará os segredos dos homens por meio de Jesus Cristo.","c":true,"v":16,"e":"O versículo 16 fala do dia em que Deus, por meio de Jesus Cristo, julgará os segredos dos homens."},
 {"t":"cv","p":"Para quem transgride a lei, a circuncisão tornou-se incircuncisão.","c":true,"v":25,"e":"O versículo 25 diz que, se a pessoa é transgressora da lei, a sua circuncisão tornou-se incircuncisão."},
 {"t":"cv","p":"Segundo o capítulo, a verdadeira circuncisão é a que é feita na carne.","c":false,"v":29,"e":"O versículo 29 diz que a verdadeira circuncisão é a do coração, no espírito, e não segundo a letra."}
]}

Romanos 15 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que Paulo diz que os fortes devem fazer?","o":["Corrigir os fracos com firmeza","Suportar as fraquezas dos fracos","Afastar-se dos fracos","Agradar a si mesmos"],"c":1,"v":1,"e":"No começo do capítulo, Paulo diz que os fortes devem suportar as fraquezas dos fracos e não agradar a si mesmos."},
 {"t":"multipla","p":"Para que foi escrito tudo o que foi escrito no passado?","o":["Para nosso ensino","Para condenar os gentios","Para ser lido só pelos sacerdotes","Para ser guardado no templo"],"c":0,"v":4,"e":"Paulo afirma que tudo foi escrito para nosso ensino, a fim de que tenhamos esperança."},
 {"t":"multipla","p":"Segundo a citação de Isaías, quem se levantará para reger os gentios?","o":["O filho de Abraão","O profeta Elias","A raiz de Jessé","O rei Salomão"],"c":2,"v":12,"e":"Isaías diz que haverá a raiz de Jessé, que se levantará para reger os gentios."},
 {"t":"multipla","p":"Onde Paulo se esforçou para anunciar o evangelho?","o":["Somente nas sinagogas","Primeiro em Roma","Onde já havia igrejas fortes","Onde Cristo ainda não tinha sido pregado"],"c":3,"v":20,"e":"Paulo diz que anunciou o evangelho onde Cristo ainda não tinha sido pregado, para não edificar sobre fundamento alheio."},
 {"t":"multipla","p":"Para onde Paulo planejava ir, passando por Roma no caminho?","o":["Egito","Espanha","Macedônia","Antioquia"],"c":1,"v":24,"e":"Paulo diz que espera visitá-los quando for a caminho da Espanha."},
 {"t":"cv","p":"Paulo diz que divulgou o evangelho desde Jerusalém até ao Ilírico.","c":true,"v":19,"e":"Paulo afirma que divulgou o evangelho de Cristo desde Jerusalém e circunvizinhanças até ao Ilírico."},
 {"t":"cv","p":"A coleta para os pobres de Jerusalém foi levantada pelos cristãos de Roma.","c":false,"v":26,"e":"A coleta foi levantada pelos macedônios e pelos da Acaia, em favor dos pobres entre os santos de Jerusalém."},
 {"t":"cv","p":"Paulo pede orações para ser livre dos rebeldes que habitam na Judeia.","c":true,"v":31,"e":"Perto do fim do capítulo, Paulo pede orações para ser livre dos rebeldes da Judeia e para que seu serviço seja bem aceito em Jerusalém."}
]}

Romanos 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo Paulo, o que foi confiado aos judeus?","o":["O templo de Jerusalém","Os oráculos de Deus","A terra prometida","As chaves do Reino"],"c":1,"v":2,"e":"No versículo 2, Paulo diz que a vantagem do judeu é que a ele foram confiados os oráculos de Deus."},
 {"t":"multipla","p":"Se alguns foram incrédulos, o que Paulo diz que deve ser considerado?","o":["Que Deus seja considerado verdadeiro e todo homem, mentiroso","Que a promessa de Deus foi cancelada","Que os incrédulos serão perdoados mesmo assim","Que a fidelidade de Deus depende da fé humana"],"c":0,"v":4,"e":"No versículo 4, Paulo responde que Deus seja considerado verdadeiro e todo homem, mentiroso."},
 {"t":"multipla","p":"De que frase Paulo diz que alguns o acusavam caluniosamente?","o":["Abandonemos a lei para viver pela graça","Deus não julgará o mundo","Pratiquemos o mal para que venham bens","Só os judeus serão salvos"],"c":2,"v":8,"e":"No versículo 8, Paulo diz que era caluniado como se afirmasse: Pratiquemos o mal para que venham bens."},
 {"t":"multipla","p":"Quem, segundo Paulo, está sob o domínio do pecado?","o":["Só os gentios","Só os que não são circuncidados","Só os que rejeitaram a lei","Todos, tanto judeus quanto gregos"],"c":3,"v":9,"e":"No versículo 9, Paulo conclui que todos, tanto judeus quanto gregos, estão sob o domínio do pecado."},
 {"t":"multipla","p":"O que se obtém pela lei, segundo o capítulo?","o":["A justificação diante de Deus","O pleno conhecimento do pecado","A redenção em Cristo","O perdão dos pecados anteriores"],"c":1,"v":20,"e":"No versículo 20, Paulo diz que é pela lei que se obtém o pleno conhecimento do pecado."},
 {"t":"cv","p":"Paulo diz que os que creem são justificados gratuitamente, por sua graça, pela redenção que há em Cristo Jesus.","c":true,"v":24,"e":"O versículo 24 afirma que são justificados gratuitamente, por sua graça, através da redenção que há em Cristo Jesus."},
 {"t":"cv","p":"Segundo Paulo, a jactância foi excluída pela lei das obras.","c":false,"v":27,"e":"No versículo 27, Paulo diz que a jactância foi excluída não pela lei das obras, mas pela lei da fé."},
 {"t":"cv","p":"Paulo conclui que, pela fé, a lei é anulada.","c":false,"v":31,"e":"No versículo 31, Paulo diz que não anulamos a lei pela fé, mas, pelo contrário, reafirmamos a lei."}
]}

Romanos 13 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o capítulo, de onde provém toda autoridade?","o":["Do povo","De Deus","Do imperador","Da lei de Moisés"],"c":1,"v":1,"e":"No versículo 1, Paulo diz que não há autoridade que não provenha de Deus."},
 {"t":"multipla","p":"Para quem os governantes são motivo de temor?","o":["Para quem pratica o bem","Para os estrangeiros","Para quem faz o mal","Para os que não pagam tributo"],"c":2,"v":3,"e":"O versículo 3 diz que os governantes não são temor para quem pratica o bem, mas para quem faz o mal."},
 {"t":"multipla","p":"Além do temor do castigo, por que é necessário estar sujeito às autoridades?","o":["Por dever de consciência","Para receber recompensa","Por medo dos vizinhos","Por tradição dos pais"],"c":0,"v":5,"e":"O versículo 5 diz que a sujeição é também por dever de consciência."},
 {"t":"multipla","p":"Qual é a única dívida que se deve continuar tendo?","o":["O tributo ao governo","A oferta ao templo","O respeito aos mais velhos","O amor uns pelos outros"],"c":3,"v":8,"e":"O versículo 8 manda não dever nada a ninguém, exceto o amor uns pelos outros."},
 {"t":"multipla","p":"Em que palavra se resumem os mandamentos citados?","o":["Não matarás","Amarás o teu próximo como a ti mesmo","Honra teu pai e tua mãe","Sujeitai-vos às autoridades"],"c":1,"v":9,"e":"O versículo 9 diz que todos os mandamentos se resumem em amar o próximo como a si mesmo."},
 {"t":"cv","p":"O capítulo afirma que o amor não faz o mal ao próximo.","c":true,"v":10,"e":"O versículo 10 diz que o amor não faz o mal ao próximo e que o cumprimento da lei é o amor."},
 {"t":"cv","p":"Paulo diz que o dia já passou e que a noite está se aproximando.","c":false,"v":12,"e":"O versículo 12 diz o contrário: a noite já passou e o dia está se aproximando."},
 {"t":"cv","p":"No fim do capítulo, Paulo manda revestir-se do Senhor Jesus Cristo.","c":true,"v":14,"e":"O versículo 14 diz para se revestirem do Senhor Jesus Cristo e não fazerem planos para a carne."}
]}

Romanos 12 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Como Paulo pede que os irmãos apresentem os seus corpos a Deus?","o":["Como sacrifício vivo, santo e aceitável","Como oferta queimada no altar","Como servos da lei de Moisés","Como templo fechado ao mundo"],"c":0,"v":1,"e":"No versículo 1, Paulo pede que apresentem os corpos como sacrifício vivo, santo e aceitável a Deus."},
 {"t":"multipla","p":"Segundo o texto, como os irmãos devem se transformar?","o":["Pelo jejum e pela oração","Pela renovação da sua mente","Pela tradição dos antigos","Pelo afastamento das cidades"],"c":1,"v":2,"e":"O versículo 2 diz que devem se transformar pela renovação da sua mente."},
 {"t":"multipla","p":"Que imagem Paulo usa para mostrar que muitos formam uma só unidade em Cristo?","o":["Um rebanho com um pastor","Uma casa com muitos cômodos","Um corpo com muitos membros","Uma árvore com muitos ramos"],"c":2,"v":5,"e":"Nos versículos 4 e 5, Paulo compara os irmãos a um só corpo em Cristo com muitos membros."},
 {"t":"multipla","p":"Quem tem o dom de exercer misericórdia deve fazê-lo com o quê?","o":["Generosidade","Zelo","Dedicação","Alegria"],"c":3,"v":8,"e":"No fim do versículo 8, quem exerce misericórdia deve fazê-lo com alegria."},
 {"t":"multipla","p":"Como os irmãos devem se portar na tribulação?","o":["Ser pacientes","Ficar em silêncio","Fugir do perigo","Buscar vingança"],"c":0,"v":12,"e":"O versículo 12 diz que devem ser pacientes na tribulação."},
 {"t":"cv","p":"O capítulo manda abençoar os que perseguem e não amaldiçoá-los.","c":true,"v":14,"e":"O versículo 14 diz: abençoem os que os perseguem; abençoem e não amaldiçoem."},
 {"t":"cv","p":"O texto permite retribuir o mal pelo mal quando a ofensa for grave.","c":false,"v":17,"e":"O versículo 17 diz para não retribuir a ninguém o mal pelo mal, sem exceção."},
 {"t":"cv","p":"O capítulo termina mandando vencer o mal com o bem.","c":true,"v":21,"e":"O versículo 21 diz para não se deixar vencer pelo mal, mas vencer o mal com o que é bom."}
]}

Romanos 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo a Escritura citada no capítulo, o que foi imputado a Abraão como justiça?","o":["Ter sido circuncidado","Ter crido em Deus","Ter obedecido à lei","Ter oferecido sacrifícios"],"c":1,"v":3,"e":"O versículo 3 cita: 'Abraão creu em Deus, e isso lhe foi imputado como justiça'."},
 {"t":"multipla","p":"Quem o capítulo cita declarando bem-aventurado o homem a quem Deus atribui justiça independentemente das obras?","o":["Moisés","Isaías","Davi","Salomão"],"c":2,"v":6,"e":"O versículo 6 diz que Davi declara bem-aventurado esse homem e cita suas palavras nos versículos 7 e 8."},
 {"t":"multipla","p":"Em que situação a fé foi imputada a Abraão para justiça?","o":["Quando ainda era incircunciso","Depois de ser circuncidado","No mesmo dia da circuncisão","Depois de receber a lei"],"c":0,"v":10,"e":"O versículo 10 responde: 'Não na circuncisão, mas sim na incircuncisão'."},
 {"t":"multipla","p":"Por meio de quê veio a promessa de que Abraão seria herdeiro do mundo?","o":["Pela lei","Pela circuncisão","Pelas obras","Pela justiça da fé"],"c":3,"v":13,"e":"O versículo 13 diz que a promessa não foi feita pela lei, mas mediante a justiça da fé."},
 {"t":"multipla","p":"Como o capítulo descreve o Deus em quem Abraão creu?","o":["Aquele que pesa as obras de cada um","Aquele que vivifica os mortos e chama à existência as coisas que não existem","Aquele que exige sacrifícios pelo pecado","Aquele que habita no templo de Jerusalém"],"c":1,"v":17,"e":"O versículo 17 descreve Deus como aquele 'que vivifica os mortos e chama à existência as coisas que não existem'."},
 {"t":"cv","p":"Ao levar em conta seu próprio corpo já amortecido, Abraão enfraqueceu na fé.","c":false,"v":19,"e":"O versículo 19 diz que ele não enfraqueceu na fé, embora levasse em conta seu corpo já amortecido."},
 {"t":"cv","p":"O capítulo diz que o registro de que a justiça foi atribuída a Abraão foi escrito somente por causa dele.","c":false,"v":24,"e":"Os versículos 23 e 24 dizem que não foi escrito somente por causa dele, mas também por nós, que cremos."},
 {"t":"cv","p":"Jesus foi entregue por nossas transgressões e ressuscitou para a nossa justificação.","c":true,"v":25,"e":"O versículo 25 diz exatamente isso sobre Jesus."}
]}

Romanos 16 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Febe era serva da igreja em qual lugar?","o":["Éfeso","Corinto","Cencréia","Antioquia"],"c":2,"v":1,"e":"No versículo 1, Paulo recomenda Febe, serva da igreja em Cencréia."},
 {"t":"multipla","p":"O que Priscila e Áquila fizeram por Paulo?","o":["Arriscaram a própria vida por ele","Pagaram as despesas da viagem dele","Escreveram a carta para ele","Visitaram-no na prisão"],"c":0,"v":4,"e":"No versículo 4, Paulo diz que eles arriscaram suas próprias vidas por causa dele."},
 {"t":"multipla","p":"De quem Paulo diz que também tem sido mãe para ele?","o":["Maria","A mãe de Rufo","Pérside","Júlia"],"c":1,"v":13,"e":"No versículo 13, Paulo saúda Rufo e a mãe dele, que também tem sido mãe para ele."},
 {"t":"multipla","p":"O que Paulo pede que façam com quem provoca divisões e escândalos?","o":["Que os corrijam em público","Que se afastem deles","Que os recebam com paciência","Que os entreguem às autoridades"],"c":1,"v":17,"e":"No versículo 17, Paulo pede que fiquem atentos a essas pessoas e se afastem delas."},
 {"t":"multipla","p":"Quem diz no capítulo que escreveu esta epístola?","o":["Timóteo","Gaio","Erasto","Tércio"],"c":3,"v":22,"e":"No versículo 22, Tércio diz que escreveu a epístola e saúda os leitores no Senhor."},
 {"t":"cv","p":"Andrônico e Júnias estavam em Cristo antes de Paulo.","c":true,"v":7,"e":"No versículo 7, Paulo diz que Andrônico e Júnias estavam em Cristo antes dele."},
 {"t":"cv","p":"Segundo Paulo, os que causam divisões servem a Cristo, mas usam palavras duras.","c":false,"v":18,"e":"No versículo 18, Paulo diz que essas pessoas não servem a Cristo, mas ao próprio ventre, e enganam com palavras suaves e lisonjas."},
 {"t":"cv","p":"O capítulo termina dando glória ao único Deus, sábio, por meio de Jesus Cristo.","c":true,"v":27,"e":"No versículo 27, a carta se encerra com glória ao único Deus, sábio, por meio de Jesus Cristo, pelos séculos dos séculos."}
]}

Romanos 7 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No exemplo de Paulo, quando a mulher casada fica livre da lei que a une ao marido?","o":["Quando se separa dele","Quando o marido morre","Quando volta para a casa do pai","Quando se casa com outro homem"],"c":1,"v":2,"e":"O versículo 2 diz que, se o marido morrer, ela fica liberada da lei que a une a ele."},
 {"t":"multipla","p":"Por meio de quê os irmãos morreram em relação à lei?","o":["Da circuncisão","Do sangue dos sacrifícios","Do corpo de Cristo","Da obediência aos mandamentos"],"c":2,"v":4,"e":"O versículo 4 diz que eles morreram em relação à lei por meio do corpo de Cristo."},
 {"t":"multipla","p":"Que mandamento Paulo cita para mostrar que a lei o fez conhecer o pecado?","o":["Não matarás","Não furtarás","Não adulterarás","Não cobiçarás"],"c":3,"v":7,"e":"No versículo 7, Paulo diz que não teria conhecido a cobiça se a lei não dissesse: Não cobiçarás."},
 {"t":"multipla","p":"O que o pecado fez com Paulo, prevalecendo-se do mandamento?","o":["Enganou-o e o conduziu à morte","Fez com que ele esquecesse a lei","Afastou-o dos irmãos","Tornou o mandamento impuro"],"c":0,"v":11,"e":"O versículo 11 diz que o pecado, por meio do mandamento, o enganou e o conduziu à morte."},
 {"t":"multipla","p":"Segundo Paulo, quem faz aquilo que ele não quer fazer?","o":["A própria lei","O pecado que habita nele","Os outros homens","O mandamento"],"c":1,"v":17,"e":"O versículo 17 diz que já não é ele quem faz isso, mas o pecado que habita nele."},
 {"t":"cv","p":"Paulo diz que a lei é carnal e que ele é espiritual.","c":false,"v":14,"e":"O versículo 14 diz o contrário: a lei é espiritual, e ele é carnal, vendido à escravidão do pecado."},
 {"t":"cv","p":"Paulo diz que, quanto ao homem interior, sente prazer na lei de Deus.","c":true,"v":22,"e":"O versículo 22 diz que, em relação ao seu homem interior, ele sente prazer na lei de Deus."},
 {"t":"cv","p":"Depois de perguntar quem o livrará do corpo desta morte, Paulo agradece a Deus por Jesus Cristo, nosso Senhor.","c":true,"v":25,"e":"Logo após a pergunta do versículo 24, o versículo 25 diz: Agradeço a Deus por Jesus Cristo, nosso Senhor."}
]}

Romanos 10 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que Paulo deseja e pede a Deus em favor de Israel?","o":["Que guardem a lei","Que voltem à sua terra","Que sejam salvos","Que reconstruam o templo"],"c":2,"v":1,"e":"No versículo 1, Paulo diz que seu desejo e sua súplica a Deus por Israel são para que sejam salvos."},
 {"t":"multipla","p":"Como Paulo descreve o zelo de Israel por Deus?","o":["Zelo sem entendimento","Entendimento sem zelo","Zelo com pleno entendimento","Falta total de zelo"],"c":0,"v":2,"e":"No versículo 2, Paulo diz que eles têm zelo por Deus, porém não com entendimento."},
 {"t":"multipla","p":"Segundo o capítulo, quem é o fim da lei, para a justiça de todo aquele que crê?","o":["Moisés","Cristo","Isaías","Abraão"],"c":1,"v":4,"e":"O versículo 4 diz que o fim da lei é Cristo, para a justiça de todo aquele que crê."},
 {"t":"multipla","p":"Além de confessar que Jesus é Senhor, o que a pessoa deve crer no coração para ser salva?","o":["Que Jesus nasceu em Belém","Que a lei foi dada a Moisés","Que Jesus voltará em breve","Que Deus o ressuscitou dentre os mortos"],"c":3,"v":9,"e":"O versículo 9 diz que quem confessar que Jesus é Senhor e crer que Deus o ressuscitou dentre os mortos será salvo."},
 {"t":"multipla","p":"De acordo com o capítulo, a fé vem pelo quê?","o":["Pelo ver","Pelo ouvir","Pelo jejuar","Pelo sacrificar"],"c":1,"v":17,"e":"O versículo 17 diz que a fé vem pelo ouvir, e o ouvir pela palavra de Cristo."},
 {"t":"cv","p":"O capítulo afirma que há distinção entre judeu e grego diante do Senhor.","c":false,"v":12,"e":"O versículo 12 diz que não há distinção entre judeu e grego, pois um único Senhor é rico para com todos os que o invocam."},
 {"t":"cv","p":"Paulo cita Moisés, que diz que Deus poria Israel em ciúmes com um povo que não é nação.","c":true,"v":19,"e":"No versículo 19, Moisés é citado dizendo: Eu vos porei em ciúmes com um povo que não é nação."},
 {"t":"cv","p":"A respeito de Israel, o capítulo termina dizendo que Deus estendeu as mãos a um povo obediente e fiel.","c":false,"v":21,"e":"O versículo 21 diz que Deus estendeu as mãos todo o dia a um povo rebelde e contradizente."}
]}

Romanos 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Logo no início da carta, Paulo se apresenta como servo de quem?","o":["De Jesus Cristo","Do rei Davi","Do apóstolo Pedro","Da igreja de Roma"],"c":0,"v":1,"e":"No versículo 1, Paulo se chama \"servo de Jesus Cristo, chamado para ser apóstolo\"."},
 {"t":"multipla","p":"Por que Paulo dá graças a Deus pelos cristãos de Roma?","o":["Porque lhe enviaram uma oferta","Porque o visitaram na prisão","Porque a fé deles é proclamada em todo o mundo","Porque fundaram muitas igrejas"],"c":2,"v":8,"e":"No versículo 8, Paulo dá graças \"porque, em todo o mundo, é proclamada a fé de vocês\"."},
 {"t":"multipla","p":"Do que Paulo diz que não se envergonha?","o":["De suas fraquezas","Do evangelho","De ser cidadão romano","De suas prisões"],"c":1,"v":16,"e":"No versículo 16, Paulo diz que não se envergonha do evangelho, que é o poder de Deus para a salvação."},
 {"t":"multipla","p":"Qual frase das Escrituras Paulo cita ao falar da justiça de Deus revelada no evangelho?","o":["\"O Senhor é o meu pastor.\"","\"Ama o teu próximo como a ti mesmo.\"","\"No princípio criou Deus os céus e a terra.\"","\"O justo viverá pela fé.\""],"c":3,"v":17,"e":"No versículo 17, Paulo cita: \"O justo viverá pela fé.\""},
 {"t":"multipla","p":"Segundo o capítulo, o que esses homens adoraram e serviram em lugar do Criador?","o":["A criatura","Os anjos","O imperador","As riquezas"],"c":0,"v":25,"e":"No versículo 25, eles \"adoraram e serviram a criatura em lugar do Criador\"."},
 {"t":"cv","p":"Paulo conta que já havia visitado os irmãos de Roma muitas vezes.","c":false,"v":13,"e":"No versículo 13, Paulo diz que muitas vezes se propôs a ir até eles, mas até então tinha sido impedido."},
 {"t":"cv","p":"Desde a criação do mundo, o eterno poder e a divindade de Deus podem ser percebidos nas coisas que foram criadas.","c":true,"v":20,"e":"O versículo 20 afirma que os atributos invisíveis de Deus podem ser reconhecidos nas coisas criadas, e por isso os homens são indesculpáveis."},
 {"t":"cv","p":"No fim do capítulo, Paulo diz que eles não só praticam essas coisas, mas também aprovam quem as pratica.","c":true,"v":32,"e":"O versículo 32 diz que \"não somente as fazem, mas também aprovam aqueles que assim agem\"."}
]}

Romanos 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Justificados mediante a fé, o que temos com Deus?","o":["Paz","Medo","Dívida","Distância"],"c":0,"v":1,"e":"O versículo 1 diz que, justificados pela fé, temos paz com Deus por meio de Jesus Cristo."},
 {"t":"multipla","p":"Segundo o capítulo, o que a tribulação produz?","o":["Esperança","Perseverança","Experiência","Tristeza"],"c":1,"v":3,"e":"O versículo 3 diz que a tribulação produz perseverança, e o versículo 4 continua a sequência até a esperança."},
 {"t":"multipla","p":"Como Deus demonstra o seu próprio amor por nós?","o":["Dando-nos a lei por meio de Moisés","Livrando-nos de toda tribulação","Cristo morreu por nós quando ainda éramos pecadores","Escolhendo apenas os justos"],"c":2,"v":8,"e":"O versículo 8 diz que Deus demonstra seu amor pelo fato de Cristo ter morrido por nós, sendo nós ainda pecadores."},
 {"t":"multipla","p":"Quando ainda éramos inimigos, fomos reconciliados com Deus por meio de quê?","o":["Da obediência à lei","Da morte de seu Filho","Das nossas boas obras","Do sacrifício de Adão"],"c":1,"v":10,"e":"O versículo 10 diz que, quando éramos inimigos, fomos reconciliados com Deus pela morte de seu Filho."},
 {"t":"multipla","p":"O que entrou no mundo por um só homem?","o":["A lei","A graça","O pecado","A esperança"],"c":2,"v":12,"e":"O versículo 12 diz que por um só homem o pecado entrou no mundo, e pelo pecado a morte."},
 {"t":"cv","p":"A morte reinou desde Adão até Moisés.","c":true,"v":14,"e":"O versículo 14 afirma que a morte reinou desde Adão até Moisés."},
 {"t":"cv","p":"Pela obediência de um só, muitos se tornarão justos.","c":true,"v":19,"e":"O versículo 19 diz que, assim como pela desobediência de um muitos se tornaram pecadores, pela obediência de um só muitos se tornarão justos."},
 {"t":"cv","p":"Onde o pecado abundou, a graça diminuiu.","c":false,"v":20,"e":"O versículo 20 diz o contrário: onde o pecado abundou, a graça superabundou."}
]}

Romanos 14 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Segundo o capítulo, o que come o débil na fé?","o":["Apenas pão","Apenas legumes","Apenas peixe","Apenas frutas"],"c":1,"v":2,"e":"No versículo 2, o débil na fé come apenas legumes, enquanto outro crê que pode comer de tudo."},
{"t":"multipla","p":"Por que quem não come não deve julgar quem come?","o":["Porque Deus o acolheu","Porque ele é mais velho na fé","Porque a lei permite","Porque ele dá esmolas"],"c":0,"v":3,"e":"O versículo 3 diz que o que não come não julgue o que come, porque Deus o acolheu."},
{"t":"multipla","p":"Sobre a distinção entre os dias, o que Paulo pede a cada um?","o":["Que siga a opinião da maioria","Que guarde todos os dias como sagrados","Que tenha a sua opinião bem definida em sua própria mente","Que pergunte aos líderes da igreja"],"c":2,"v":5,"e":"No versículo 5, Paulo pede que cada um tenha a sua opinião bem definida em sua própria mente."},
{"t":"multipla","p":"Com que propósito Cristo morreu e ressuscitou, segundo o capítulo?","o":["Para julgar os que comem carne","Para acabar com a distinção entre os dias","Para ser aprovado pelos homens","Para ser Senhor tanto dos mortos quanto dos vivos"],"c":3,"v":9,"e":"O versículo 9 diz que Cristo morreu e ressuscitou para ser Senhor tanto dos mortos quanto dos vivos."},
{"t":"multipla","p":"Segundo o capítulo, o Reino de Deus não se resume a comida ou bebida, mas a quê?","o":["Jejum, oração e esmola","Justiça, paz e alegria no Espírito Santo","Lei, sacrifício e templo","Fé, esperança e caridade"],"c":1,"v":17,"e":"O versículo 17 diz que o Reino de Deus é justiça, paz e alegria no Espírito Santo."},
{"t":"cv","p":"Paulo afirma que certas coisas são impuras em si mesmas para todas as pessoas.","c":false,"v":14,"e":"No versículo 14, Paulo diz que nada é impuro em si mesmo, exceto para aquele que assim o considera."},
{"t":"cv","p":"O capítulo diz que é melhor não comer carne nem beber vinho se isso levar o irmão a tropeçar.","c":true,"v":21,"e":"O versículo 21 diz que é melhor não comer carne nem beber vinho, nem fazer nada que leve o irmão a tropeçar."},
{"t":"cv","p":"Quem come com dúvidas está livre de condenação, desde que dê graças a Deus.","c":false,"v":23,"e":"O versículo 23 diz que quem tem dúvidas ao comer está condenado, porque não age com fé."}
]}

Romanos 8 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Para quem, segundo o início do capítulo, já não há condenação?","o":["Para os que estão em Cristo Jesus","Para os que guardam toda a lei","Para os que nunca pecaram","Para os que oferecem sacrifícios"],"c":0,"v":1,"e":"O versículo 1 diz que já não há condenação para os que estão em Cristo Jesus."},
 {"t":"multipla","p":"A que conduz a inclinação do Espírito?","o":["À sabedoria e ao conhecimento","À riqueza e à honra","À vida e à paz","À força e à vitória"],"c":2,"v":6,"e":"O versículo 6 diz que a inclinação do Espírito conduz à vida e à paz, enquanto a da carne conduz à morte."},
 {"t":"multipla","p":"Que espírito os leitores receberam, pelo qual clamam \"Aba, Pai\"?","o":["Espírito de escravidão","Espírito de adoção","Espírito de medo","Espírito de profecia"],"c":1,"v":15,"e":"O versículo 15 diz que não receberam espírito de escravidão, mas o espírito de adoção, pelo qual clamam \"Aba, Pai\"."},
 {"t":"multipla","p":"O que o capítulo diz que toda a criação faz até agora?","o":["Descansa em silêncio","Louva a Deus com alegria","Espera sem nenhum sofrimento","Geme e sofre as dores de parto"],"c":3,"v":22,"e":"O versículo 22 diz que toda a criação geme e sofre as dores de parto até agora."},
 {"t":"multipla","p":"Por que o Espírito nos auxilia e intercede por nós?","o":["Porque não temos fé suficiente","Porque esquecemos as Escrituras","Porque não sabemos orar como convém","Porque Deus não nos ouve"],"c":2,"v":26,"e":"O versículo 26 diz que o Espírito nos auxilia nas fraquezas, pois não sabemos orar como convém."},
 {"t":"cv","p":"O capítulo diz que Cristo Jesus está à direita de Deus e intercede por nós.","c":true,"v":34,"e":"O versículo 34 afirma que Cristo Jesus está à direita de Deus e também intercede por nós."},
 {"t":"cv","p":"A citação do capítulo diz que somos considerados como leões para a batalha.","c":false,"v":36,"e":"O versículo 36 diz que somos considerados como ovelhas para o matadouro."},
 {"t":"cv","p":"Paulo afirma que nem a altura nem a profundidade poderão nos separar do amor de Deus.","c":true,"v":39,"e":"O versículo 39 diz que nem a altura, nem a profundidade, nem qualquer outra criatura poderá nos separar do amor de Deus."}
]}

Romanos 6 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Qual é a resposta à pergunta \"Permaneceremos no pecado, para que a graça se torne ainda mais abundante?\"","o":["Sim, para que a graça cresça","De forma nenhuma!","Só enquanto estivermos sob a lei","Apenas até sermos batizados"],"c":1,"v":2,"e":"No versículo 2 vem a resposta: \"De forma nenhuma!\", pois quem morreu para o pecado não pode continuar a viver nele."},
 {"t":"multipla","p":"Segundo o texto, para que fomos sepultados com Cristo na morte pelo batismo?","o":["Para nos livrarmos da lei","Para sermos lembrados do pecado","Para andarmos em novidade de vida","Para recebermos a glória do Pai"],"c":2,"v":4,"e":"O versículo 4 diz que fomos sepultados com ele \"a fim de que [...] também andemos nós em novidade de vida\"."},
 {"t":"multipla","p":"O que foi crucificado com Cristo?","o":["O nosso velho homem","O nosso corpo mortal","A lei","A morte"],"c":0,"v":6,"e":"O versículo 6 diz que \"o nosso velho homem foi crucificado com ele\"."},
 {"t":"multipla","p":"Depois que Cristo ressuscitou dentre os mortos, o que já não tem domínio sobre ele?","o":["O pecado","A lei","A carne","A morte"],"c":3,"v":9,"e":"O versículo 9 afirma que Cristo já não morre e que \"a morte já não tem domínio sobre ele\"."},
 {"t":"multipla","p":"Por que o pecado não terá domínio sobre os leitores da carta?","o":["Porque foram circuncidados","Porque não estão sob a lei, mas sob a graça","Porque guardam toda a lei","Porque já não têm corpo mortal"],"c":1,"v":14,"e":"O versículo 14 explica: \"pois não estão sob a lei, mas sob a graça\"."},
 {"t":"cv","p":"Uma vez libertados do pecado, eles se tornaram servos da justiça.","c":true,"v":18,"e":"O versículo 18 diz exatamente isso: \"uma vez libertados do pecado, vocês se tornaram servos da justiça\"."},
 {"t":"cv","p":"Paulo diz que o fim das coisas de que eles agora se envergonham é a vida.","c":false,"v":21,"e":"No versículo 21, Paulo diz que o fim dessas coisas é a morte."},
 {"t":"cv","p":"O salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus, nosso Senhor.","c":true,"v":23,"e":"O versículo 23, último do capítulo, diz exatamente isso."}
]}
